 const tokens=actual.tokens(actual.source),components=proof.delegated?.components,fields=components?.fields||[],value=fields[0]?.actual.value,sourceToken=(value?actual.tokens(value):tokens).find(t=>t.owners.some(Boolean)&&t.end-t.start>1);assert(sourceToken);const offset=sourceToken.start+1;mapping('original initializer UTF-16 interior retarget',offset,wrong);mapping('original initializer UTF-16 interior erase',offset,null);
 if(fields.length){const item=fields.find(p=>p.field.modifiers?.some(m=>m.kind===ts.SyntaxKind.StaticKeyword));assert(item);mapping('complete static expression logical endpoint',item.actual.expression.end,wrong);mapping('complete static statement logical endpoint',item.actual.node.end,wrong);const literal=actual.tokens(item.actual.value).find(t=>t.text==='1');assert(literal);code('original static initializer effect',literal.start,literal.end,'9');}
 const classRoot=proof.classes?.[0]?.actual.node;if(classRoot)mapping('complete original class binding endpoint',classRoot.end,wrong);
 const generated=components?.helpers?.actual.definitions?.[0];if(generated){mapping('generated helper algorithm source grant',generated.getStart(actual.source)+1,wrong);const operation=actual.tokens(generated).find(t=>t.text==='--'||t.text==='++');assert(operation);code('decorator algorithm iteration order',operation.start,operation.end,operation.text==='--'?'++':'--');}
 const classCall=components?.actual.binding?.call;if(classCall){const statement=classCall.parent;assert(ts.isExpressionStatement(statement));code('omit class replacement decoration phase',statement.getStart(actual.source),statement.end,actual.code.slice(statement.getStart(actual.source),statement.end).replace(/[^\r\n]/g,' '));const entry=[...components.actual.memberBindings.entries.values()][0],queue=entry.initializers;code('member initializer queue identity',queue.getStart(actual.source),queue.getStart(actual.source)+1,'Z');}
 let gap;for(let i=1;i<tokens.length;i++){const x=tokens[i-1],y=tokens[i];if(x.end<y.start&&actual.owner(x.end)){gap=x.end;break;}}if(gap!==undefined)mapping('ordered physical source gap retarget',gap,wrong);
